import React from "react";
import BookList from "./BookList";
import "../styles.css";

// Пример данных (можно заменить на API-запрос)
const books = [
  { title: "Unlocking Android", author: "Frank Ableson" },
  { title: "Flex 3 in Action", author: "Tariq Ahmed" },
  { title: "Specification by Example", author: "Gojko Adzic" },
  { title: "MongoDB in Action", author: "Kyle Banker" },
  { title: "Hibernate in Action", author: "Gavin King" },
  { title: "jQuery in Action", author: "Bear Bibeault" },
];

const App = () => {
  return (
    <div className="app">
      <h1>Библиотека</h1>
      <BookList books={books} />
    </div>
  );
};

export default App;
